class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        maxq = deque()  # indices, values decreasing
        minq = deque()  # indices, values increasing
        n = len(nums)
        l = 0
        total = 0
        for r in range(n):
            x = nums[r]
            while maxq and nums[maxq[-1]] <= x:
                maxq.pop()
            maxq.append(r)
            while minq and nums[minq[-1]] >= x:
                minq.pop()
            minq.append(r)
            while nums[maxq[0]] - nums[minq[0]] > 2:
                l += 1
                if maxq[0] < l:
                    maxq.popleft()
                if minq[0] < l:
                    minq.popleft()
            total += r - l + 1
        return total

