import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # small values, many duplicates and near-duplicates
        nums = draw(st.lists(st.integers(1, 5), min_size=n, max_size=n))
    elif mode == 1:
        # sorted ascending
        nums = sorted(draw(st.lists(st.integers(1, 10**9 if False else 8), min_size=n, max_size=n)))
    elif mode == 2:
        # sorted descending
        nums = sorted(draw(st.lists(st.integers(1, 8), min_size=n, max_size=n)), reverse=True)
    else:
        # all equal, or extremes of the value range scaled down
        v = draw(st.integers(1, 3))
        nums = draw(st.sampled_from([[v] * n, [1, 10**9] * (n // 2) + [1] * (n % 2)]))
    return json.dumps(nums)

def validate(inp):
    try:
        lines = [l for l in inp.split("\n") if l.strip() != ""]
        if len(lines) != 1:
            return False
        nums = json.loads(lines[0])
        if not isinstance(nums, list):
            return False
        if not (1 <= len(nums) <= 10**5):
            return False
        for x in nums:
            if type(x) is not int:
                return False
            if not (1 <= x <= 10**9):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    nums = json.loads(inp.strip())
    n = len(nums)
    count = 0
    for i in range(n):
        for j in range(i, n):
            sub = nums[i:j + 1]
            if max(sub) - min(sub) <= 2:
                count += 1
    return json.dumps(count)
